class Hotel:
    SINGLE = 'single'
    DOUBLE = 'double'

    def __init__(self, name, rooms):
        self.name = name
        self._available_rooms = rooms
        # available_rooms = {room_type1: room_number1, room_type2: room_number2, ...}
        # available_rooms = {'single': 5, 'double': 3}
        self._booked_rooms = {}
        # booked_rooms = {room_type1: {name1: room_number1, name2: room_number2, ...}, room_type2: {...}, ...}
        # booked_rooms = {'single': {'name1': 2, 'name2':1}, 'double': {}}

    @property
    def available_rooms(self):
        return self._available_rooms

    @available_rooms.setter
    def available_rooms(self, rooms):
        self._available_rooms = rooms

    @property
    def booked_rooms(self):
        return self._booked_rooms

    @booked_rooms.setter
    def booked_rooms(self, booked):
        self._booked_rooms = booked

    def _get_available_count(self, room_type):
        return self.available_rooms.get(room_type, 0)

    def _ensure_room_type_in_booked(self, room_type):
        if room_type not in self.booked_rooms:
            self.booked_rooms[room_type] = {}

    def _can_book(self, room_type, room_number):
        available_count = self._get_available_count(room_type)
        return room_type in self.available_rooms and room_number <= available_count

    def book_room(self, room_type, room_number, name):
        if not self._can_book(room_type, room_number):
            available_count = self._get_available_count(room_type)
            if available_count != 0:
                return available_count
            return False

        self._ensure_room_type_in_booked(room_type)
        self.booked_rooms[room_type][name] = room_number
        self._reduce_available_rooms(room_type, room_number)
        return "Success!"

    def _reduce_available_rooms(self, room_type, room_number):
        self.available_rooms[room_type] -= room_number

    def _can_check_in(self, room_type, name, room_number):
        if room_type not in self.booked_rooms:
            return False
        if name not in self.booked_rooms[room_type]:
            return False
        return room_number <= self.booked_rooms[room_type][name]

    def check_in(self, room_type, room_number, name):
        if not self._can_check_in(room_type, name, room_number):
            return False

        booked_count = self.booked_rooms[room_type][name]
        if room_number == booked_count:
            self._remove_guest(room_type, name)
        else:
            self._reduce_booked_room(room_type, name, room_number)

    def _remove_guest(self, room_type, name):
        self.booked_rooms[room_type].pop(name)

    def _reduce_booked_room(self, room_type, name, room_number):
        self.booked_rooms[room_type][name] -= room_number

    def check_out(self, room_type, room_number):
        self._add_to_available_rooms(room_type, room_number)

    def _add_to_available_rooms(self, room_type, room_number):
        if room_type in self.available_rooms:
            self.available_rooms[room_type] += room_number
        else:
            self.available_rooms[room_type] = room_number

    def get_available_rooms(self, room_type):
        return self.available_rooms.get(room_type, 0)
